package com.personal.assistant.module.report.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.report.dto.ReportStats;import com.personal.assistant.module.report.entity.GeneratedReport;import com.personal.assistant.module.report.mapper.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;@Service public class ReportService{private final GeneratedReportMapper reports;private final ReportStatsMapper stats;public ReportService(GeneratedReportMapper reports,ReportStatsMapper stats){this.reports=reports;this.stats=stats;}public List<GeneratedReport>list(Long uid){return reports.selectList(new LambdaQueryWrapper<GeneratedReport>().eq(GeneratedReport::getUserId,uid).orderByDesc(GeneratedReport::getPeriodEnd).last("limit 100"));}@Transactional public GeneratedReport generate(Long uid,String type,LocalDate reference){LocalDate start;LocalDate end;if("WEEKLY".equals(type)){start=reference.with(java.time.DayOfWeek.MONDAY);end=start.plusDays(6);}else if("MONTHLY".equals(type)){start=reference.withDayOfMonth(1);end=reference.withDayOfMonth(reference.lengthOfMonth());}else throw new BusinessException(ErrorCode.VALIDATION_ERROR,"报告类型仅支持 WEEKLY 或 MONTHLY");ReportStats value=stats.stats(uid,start,end);String title=("WEEKLY".equals(type)?"个人周报 ":"个人月报 ")+start+" 至 "+end;String markdown="# "+title+"\n\n## 行动与成长\n\n- 新建任务："+value.createdTasks()+"\n- 完成任务："+value.completedTasks()+"\n- 学习时长："+value.learningMinutes()+" 分钟\n- 开发沉淀："+value.devLogCount()+" 条\n\n## 财务摘要\n\n- 收入：¥"+value.income()+"\n- 支出：¥"+value.expense()+"\n- 结余：¥"+value.income().subtract(value.expense())+"\n\n> 本报告由确定性统计自动生成，不包含投资建议。";GeneratedReport report=reports.selectOne(new LambdaQueryWrapper<GeneratedReport>().eq(GeneratedReport::getUserId,uid).eq(GeneratedReport::getReportType,type).eq(GeneratedReport::getPeriodStart,start).eq(GeneratedReport::getPeriodEnd,end));boolean create=report==null;if(create)report=new GeneratedReport();report.setUserId(uid);report.setReportType(type);report.setPeriodStart(start);report.setPeriodEnd(end);report.setTitle(title);report.setMarkdownContent(markdown);report.setCreatedAt(LocalDateTime.now());if(create)reports.insert(report);else reports.updateById(report);return report;}}
